require 'json'

class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    entry = if @packer
              @packer.dump(payload)
            else
              payload
            end
    @store[key] = { value: entry, stale: stale }
  end

  def read(key)
    entry = @store[key]
    return nil unless entry

    payload = if @packer
                @packer.load(entry[:value])
              else
                entry[:value]
              end

    # If the entry was marked stale, it is removed on sweep but still
    # considered "never written" after sweep if it has not been removed yet.
    # The specification says #read returns nil for entries removed by #sweep.
    # Since we have not called sweep yet, we still return the payload.
    # However, if stale is true we do not remove it here; sweep does that.
    payload
  end

  def sweep
    @store.each_key do |key|
      entry = @store[key]
      if entry[:stale]
        @store.delete(key)
      end
    end
  end
end
