class Proxy
  attr_reader :target

  def initialize(target)
    @target = target
  end

  def method_missing(name, *args, &block)
    @target.send(name, *args, &block)
  end

  def respond_to_missing?(name, include_private = false)
    @target.respond_to?(name, include_private) || self.class.respond_to?(name, include_private)
  end

  def method(name)
    if @target.respond_to?(name)
      super(name) # defines the method on Proxy for future calls
    else
      raise NameError, "undefined method `#{name}' for #{self.class}:#{object_id}"
    end
  end
