  include Enumerable

  def initialize
    @store = {}
    @keys = []
  end

  def []=(index, value)
    unless @store.key?(index)
      @store[index] = value
      @keys << index
      @keys.sort!
    end
    @store[index] = value
  end

  def each
    @keys.each { |index| yield @store[index] }
  end

  def sum
    inject(0, :+)
  end

  def count
    @keys.length
  end

  def select
    result = SparseArray.new
    each_with_index do |value, idx|
      if yield(value)
        result[@keys[idx]] = value
      end
    end
    result
  end

  def map
    result = []
    each { |value| result << yield(value) }
    result
  end
