class Steps
  include Enumerable

  attr_reader :from

  def initialize(from)
    @from = from
  end

  def each(block = nil)
    if block
      @from.downto(1) { |i| block.call(i) }
      self
    else
      StepsEnumerator.new(self)
    end
  end

  private

  class StepsEnumerator
    include Enumerable

    def initialize(steps)
      @steps = steps
      @current = steps.from
    end

    def next
      if @current >= 1
        value = @current
        @current -= 1
        value
      else
        raise StopIteration
      end
    end

    def with_index
      idx = 0
      @steps.from.downto(1) do |val|
        yield [val, idx]
        idx += 1
      end
      @steps
    end

    def to_a
      result = []
      @steps.from.downto(1) { |val| result << val }
      result
    end

    def each(&block)
      @steps.from.downto(1) { |i| block.call(i) }
      @steps
    end
  end
end
