# frozen_string_literal: true

class LazyEnumerable
  include Enumerable

  def initialize(enum, &predicate)
    @enum = enum
    @predicate = predicate
    @buffer = []
    @buffer_index = 0
    @closed = false
  end

  def first(n = 1)
    results = []
    until results.size >= n || @closed
      if @buffer_index < @buffer.size
        val = @buffer[@buffer_index]
        @buffer_index += 1
        if @predicate.call(val)
          results << val
        end
      else
        begin
          elem = @enum.peek || @enum.next
        rescue StopIteration
          @closed = true
          break
        end
        @buffer << elem
        @buffer_index = 0
      end
    end
    results.each { |v| yield v } if block_given?
    results
  end

  def first!
    first { raise "no more elements" }
  end

  def method_missing(method, *args, &block)
    if @enum.respond_to?(method)
      # Return a new LazyEnumerable that wraps both enums and applies
      # the method (e.g. select) to the underlying source, keeping
      # our own predicate intact.
      source = @enum.send(method, *args, &block)
      LazyEnumerable.new(source) do |elem|
        @predicate.call(elem) && @predicate.call(elem)
      end
    else
      super
    end
  end

  def respond_to_missing?(method, include_private = false)
    @enum.respond_to?(method) || super
  end

  def each(&block)
    # Materialize any remaining buffered elements then delegate to enum.
    until @buffer_index >= @buffer.size
      yield @buffer[@buffer_index]
      @buffer_index += 1
    end
    @enum.each(&block)
  end
end

def Finder
  @finder ||= Module.new do
    def self.first_matching(source, &predicate)
      LazyEnumerable.new(source, &predicate)
    end
  end
end
